export const ENTITIES: EntityDef[] = RAW.map(([entity, provider, label, minimal, fields]) => ({
  entity, provider, label, minimal,
  fields: fields.map(([key, fieldLabel]) => ({ key, label: fieldLabel })),
}));

export const ENTITY_BY_KEY: Record<string, EntityDef> = Object.fromEntries(ENTITIES.map((e) => [e.entity, e]));
export const ENTITIES_BY_PROVIDER: Record<string, EntityDef[]> = ENTITIES.reduce<Record<string, EntityDef[]>>((acc, e) => {
  (acc[e.provider] ??= []).push(e);
  return acc;
}, {});

